//! Loading rules: the rule set is embedded in the binary at build time (see
//! `build.rs`) and can also be augmented from an external directory at runtime.

use crate::rule::Rule;
use crate::yaml;
use std::path::Path;

// Generated by build.rs: `pub static BUILTIN_RULES: &[(&str, &str)]`.
include!(concat!(env!("OUT_DIR"), "/builtin_rules.rs"));

#[derive(Debug)]
pub struct LoadError {
    pub source: String,
    pub error: String,
}

#[derive(Debug, Default)]
pub struct Loaded {
    pub rules: Vec<Rule>,
    pub errors: Vec<LoadError>,
}

/// Load every rule embedded in the binary.
pub fn load_builtin() -> Loaded {
    let mut loaded = Loaded::default();
    for (name, content) in BUILTIN_RULES {
        parse_str(name, content, &mut loaded);
    }
    loaded
}

/// Parse a YAML string (possibly multiple `---`-separated rules) into the set.
pub fn parse_str(source: &str, contents: &str, loaded: &mut Loaded) {
    match yaml::parse_documents(contents) {
        Ok(docs) => {
            for doc in docs {
                match Rule::from_value(&doc) {
                    Ok(rule) => {
                        let problems = rule.validate();
                        if problems.is_empty() {
                            loaded.rules.push(rule);
                        } else {
                            loaded.errors.push(LoadError {
                                source: source.to_string(),
                                error: problems.join("; "),
                            });
                        }
                    }
                    Err(e) => loaded.errors.push(LoadError {
                        source: source.to_string(),
                        error: e,
                    }),
                }
            }
        }
        Err(e) => loaded.errors.push(LoadError {
            source: source.to_string(),
            error: e,
        }),
    }
}

/// Load rules from a directory tree on disk (recursively).
pub fn load_dir(path: &Path) -> Result<Loaded, String> {
    let mut loaded = Loaded::default();
    load_dir_inner(path, &mut loaded)
        .map_err(|e| format!("reading rules from {}: {e}", path.display()))?;
    Ok(loaded)
}

fn load_dir_inner(path: &Path, loaded: &mut Loaded) -> std::io::Result<()> {
    for entry in std::fs::read_dir(path)? {
        let entry = entry?;
        let p = entry.path();
        if p.is_dir() {
            load_dir_inner(&p, loaded)?;
        } else if is_rule_file(&p) {
            let name = p.display().to_string();
            match std::fs::read_to_string(&p) {
                Ok(contents) => parse_str(&name, &contents, loaded),
                Err(e) => loaded.errors.push(LoadError {
                    source: name,
                    error: e.to_string(),
                }),
            }
        }
    }
    Ok(())
}

fn is_rule_file(p: &Path) -> bool {
    matches!(
        p.extension().and_then(|e| e.to_str()),
        Some("yml") | Some("yaml")
    )
}
